function receipt = f90_xcomm02_extract_candidate_evidence(modelPath, outDir)
%F90_XCOMM02_EXTRACT_CANDIDATE_EVIDENCE Extract fixed evidence in one persistent session.
%
% This is the single MATLAB evidence entry.  It executes the unchanged
% source model_init once, disables the loaded model InitFcn only in memory,
% and then injects all five scenarios without saving the source model.
arguments
    modelPath (1,1) string = ""
    outDir (1,1) string = ""
end

scriptDir = fileparts(mfilename("fullpath"));
root = string(fileparts(fileparts(fileparts(fileparts(scriptDir)))));
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
referenceRoot = fullfile(taskRoot, "reference", "files");
modelRoot = fullfile(referenceRoot, "mvdr_4x4");
taskManifestPath = fullfile(taskRoot, "task.json");
assert(strlength(taskRoot) > 0 && isfile(taskManifestPath), ...
    "SimuVerity:F90:XCOMM02:ReferenceManifest", ...
    "The public task manifest is unavailable.");
taskManifest = jsondecode(fileread(taskManifestPath));
assert(isstruct(taskManifest) && isscalar(taskManifest) && ...
    isfield(taskManifest, "reference") && isstruct(taskManifest.reference), ...
    "SimuVerity:F90:XCOMM02:ReferenceManifest", ...
    "The public task manifest lacks the reference contract.");
expectedReferenceFilePresence = "present";
if strlength(modelPath) == 0
    modelPath = fullfile(modelRoot, "mvdr_4x4_partial_systolic.slx");
end

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XCOMM02:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
if strlength(outDir) == 0
    outDir = fullfile(tempdir, "SimuVerity", "F90-XCOMM-02", generationRunId);
end
assert(~isfolder(outDir), "SimuVerity:F90:XCOMM02:OutputReuse", ...
    "Evidence output already exists for GenerationRunId %s.", generationRunId);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XCOMM02:Isolation", ...
    "Isolated Simulink cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");

official = jsondecode(fileread(simuverity_official_scenarios_path()));
addpath(modelRoot);
addpath(fullfile(referenceRoot, "common"));
addpath(scriptDir);
assert(isfile(modelPath), "SimuVerity:F90:XCOMM02:ModelMissing", ...
    "Model is missing: %s", modelPath);
modelFilePresence = localFilePresence(modelPath);
isReference = lower(strtrim(string(getenv("SIMUVERITY_EVALUATION_SUBJECT")))) == "reference";
evaluationSubject = lower(strtrim(string( ...
    getenv("SIMUVERITY_EVALUATION_SUBJECT"))));
if strlength(evaluationSubject) == 0
    evaluationSubject = "candidate";
end
assert(any(evaluationSubject == ["candidate", "reference"]), ...
    "SimuVerity:F90:XCOMM02:EvaluationSubject", ...
    "Unsupported evaluation subject: %s", evaluationSubject);
if evaluationSubject == "reference"
    assert(isReference, "SimuVerity:F90:XCOMM02:ReferenceIdentity", ...
        "Reference evaluation model file presence differs from task.json.");
end

receipt = struct;
receipt.schema = "simuverity.f90-xcomm02-evidence.v1";
receipt.task_id = "F90-XCOMM-02";
if isReference
    receipt.adapter = ...
        "unchanged_direct_golden_in_memory_scenario_injection";
else
    receipt.adapter = "candidate_public_timeseries_contract";
end
receipt.subject_file_presence = modelFilePresence;
receipt.is_reference = isReference;
receipt.reference_substantive_modifications = 0;
receipt.extraction_only = true;
receipt.contains_score_decisions = false;
receipt.load_pass = false;
receipt.update_pass = false;
receipt.compile_pass = false;
receipt.initfcn = struct;
receipt.static_audit = struct;
receipt.scenarios = repmat(localEmptyScenario, ...
    numel(official.scenarios), 1);
receipt.errors = struct;
receipt.started_at = localNow;
receipt.runtime = struct( ...
    "generation_run_id", generationRunId, ...
    "matlab_release", string(version("-release")), ...
    "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
    "appdata", string(getenv("APPDATA")), ...
    "temp", string(getenv("TEMP")), ...
    "cache", cacheDir, ...
    "codegen", codegenDir, ...
    "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")));

[~, model] = fileparts(modelPath);
old = pwd;
cleanupDir = onCleanup(@() cd(old)); %#ok<NASGU>
scenarioArtifacts = repmat(localEmptyArtifact, ...
    numel(official.scenarios), 1);
try
    cd(modelRoot);
    initScript = fullfile(modelRoot, "model_init.m");
    if isReference
        evalin("base", "run('" + localQuote(initScript) + "');");
        generator = localGeneratorFromBase;
    else
        generator = localInitializeGenerator(initScript);
    end
    candidateRoot = string(fileparts(modelPath));
    addpath(candidateRoot);
    cd(candidateRoot);
    load_system(modelPath);
    modelCleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    receipt.load_pass = true;

    originalInitFcn = string(get_param(model, "InitFcn"));
    if isReference
        assert(contains(lower(originalInitFcn), "model_init"), ...
            "SimuVerity:F90:XCOMM02:UnexpectedInitFcn", ...
            "The source model InitFcn is not the expected model_init callback.");
        set_param(model, "InitFcn", "");
    end
    receipt.initfcn = struct( ...
        "original_callback", originalInitFcn, ...
        "source_init_executed_once", true, ...
        "disabled_in_loaded_model_only", isReference, ...
        "model_save_forbidden", true);

    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "off", ...
        "StopTime", num2str(double( ...
            official.simulation.reference_stop_tick), "%.15g"));
    [truth, requested] = localApplyScenario( ...
        official.scenarios(1), generator, isReference);
    receipt.first_update_inputs = requested;
    try
        set_param(model, "SimulationCommand", "update");
        if ~isReference
            % Allow a candidate callback to configure its loaded model once.
            % Then freeze that loaded configuration and re-assert evaluator
            % inputs so the callback cannot replace a official scenario.
            set_param(model, "InitFcn", "");
            receipt.initfcn.disabled_in_loaded_model_only = true;
            receipt.initfcn.candidate_callback_allowed_once = ...
                strlength(originalInitFcn) > 0;
            localApplyScenario( ...
                official.scenarios(1), generator, isReference);
            set_param(model, "SimulationCommand", "update");
        end
        receipt.update_pass = true;
    catch ME
        receipt.errors.update = localError(ME);
    end
    if receipt.update_pass
        compiled = false;
        try
            feval(model, [], [], [], "compile");
            compiled = true;
            receipt.compile_pass = true;
            try
                receipt.static_audit = localStaticAudit(model, isReference);
            catch ME
                receipt.errors.static_audit = localError(ME);
            end
        catch ME
            receipt.errors.compile = localError(ME);
        end
        if compiled
            try
                feval(model, [], [], [], "term");
            catch
            end
        end
    end
    if isempty(fieldnames(receipt.static_audit))
        try
            receipt.static_audit = localStaticAudit(model, isReference);
        catch ME
            receipt.errors.static_audit = localError(ME);
        end
    end

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for index = 1:numel(official.scenarios)
        scenario = official.scenarios(index);
        rows(index).id = string(scenario.id);
        try
            [truth, requested] = localApplyScenario( ...
                scenario, generator, isReference);
            rows(index).requested_inputs = requested;
            localClearEvidenceOutputs(isReference);
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            if isReference
                [summary, artifact, selected] = ...
                    localExtractReferenceEvidence(simOut, truth);
            else
                [summary, artifact, selected] = ...
                    localExtractPublicEvidence(simOut, truth);
            end
            rows(index).simulation_pass = true;
            rows(index).valid = true;
            rows(index).selected_native_signals = selected;
            rows(index).summary = summary;
            scenarioArtifacts(index) = artifact;
        catch ME
            rows(index).simulation_pass = false;
            rows(index).valid = false;
            rows(index).error = localError(ME);
        end
    end
    receipt.scenarios = rows;
    rawPath = fullfile(outDir, "raw_evidence.mat");
    save(rawPath, "scenarioArtifacts", "-v7.3");
    receipt.raw_artifact = struct( ...
        "path", string(rawPath), ...
        "format", "MAT-v7.3", ...
        "variable", "scenarioArtifacts");
catch ME
    receipt.errors.session = localError(ME);
end

localCloseModel(model);
receipt.model_closed_without_save = ~bdIsLoaded(model);
receipt.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, receipt);
fprintf("F90_XCOMM02_EVIDENCE load=%d update=%d compile=%d valid=%d/%d path=%s\n", ...
    receipt.load_pass, receipt.update_pass, receipt.compile_pass, ...
    sum([receipt.scenarios.valid]), numel(receipt.scenarios), ...
    evidencePath);
end

function audit = localStaticAudit(model, isReference)
if ~isReference
    audit = localCandidateStaticAudit(model);
    return;
end
top = string(find_system(model, "SearchDepth", 1, ...
    "FollowLinks", "off", "LookUnderMasks", "none", ...
    "Type", "Block"));
dataSource = localFindByParameter(top, "X", "sim_data_in");
validSource = localFindByParameter(top, "X", "sim_valid_in");
steeringSource = localFindByContains(top, "Value", "sv");
loadingSource = localFindByParameter(top, "Value", "diagLoading");
dataSink = localFindByParameter(top, "VariableName", "data_out");
validSink = localFindByParameter(top, "VariableName", "valid_out");

dut = string(model) + "/MVDR HDL";
stages = [ ...
    dut + "/Form Covariance Matrix", ...
    dut + "/Moving Average", ...
    dut + "/Diagonal Loading", ...
    dut + "/Compute Weight Vector", ...
    dut + "/Normalize Response", ...
    dut + "/Form Beam"];
stagePresent = arrayfun(@(path) ...
    getSimulinkBlockHandle(path, false) > 0, stages);
stageConnected = all(stagePresent);
if stageConnected
    for index = 1:(numel(stages) - 1)
        stageConnected = stageConnected && ...
            localDirectedReachable(stages(index), stages(index + 1));
    end
end

rootConnected = ...
    localDirectedReachable(dataSource, dut) && ...
    localDirectedReachable(validSource, dut) && ...
    localDirectedReachable(steeringSource, dut) && ...
    localDirectedReachable(loadingSource, dut) && ...
    localDirectedReachable(dut, dataSink) && ...
    localDirectedReachable(dut, validSink);

audit = struct;
audit.locator_policy = ...
    "native top-level parameter contracts plus stable semantic paths; no SID";
audit.data_source = dataSource;
audit.valid_source = validSource;
audit.steering_source = steeringSource;
audit.loading_source = loadingSource;
audit.dut = dut;
audit.data_sink = dataSink;
audit.valid_sink = validSink;
audit.stage_paths = stages;
audit.stage_present = stagePresent;
audit.stage_chain_connected = stageConnected;
audit.root_io_connected = rootConnected;
audit.four_input_three_output_dut = false;
if getSimulinkBlockHandle(dut, false) > 0
    ports = get_param(dut, "PortHandles");
    audit.four_input_three_output_dut = ...
        numel(ports.Inport) == 4 && numel(ports.Outport) == 3;
end
    [audit.compiled_core_types, audit.compiled_stage_fixed_point] = ...
        localCompiledFixedPointEvidence(stages);
    audit.fixed_point_evidence = ...
        all(audit.compiled_stage_fixed_point);
audit.core_path_qualified = ...
    strlength(dataSource) > 0 && ...
    strlength(validSource) > 0 && ...
    strlength(steeringSource) > 0 && ...
    strlength(loadingSource) > 0 && ...
    strlength(dataSink) > 0 && ...
    strlength(validSink) > 0 && ...
    all(stagePresent) && stageConnected && rootConnected && ...
    audit.four_input_three_output_dut;
end

function audit = localCandidateStaticAudit(model)
blocks = string(find_system(model, ...
    "FollowLinks", "on", "LookUnderMasks", "all", ...
    "Type", "Block"));
inputs = ["ArrayData", "InputValid", ...
    "SteeringVector", "DiagonalLoading"];
outputs = ["BeamformedOutput", "OutputValid", ...
    "WeightVector", "WeightValid", ...
    "CovarianceMatrix", "CovarianceValid", ...
    "LoadedCovarianceMatrix", "LoadedCovarianceValid", ...
    "SolveVector", "SolveValid", ...
    "NormalizationState", "NormalizationValid"];
inputBindings = strings(size(inputs));
for index = 1:numel(inputs)
    inputBindings(index) = localFindTokenAcrossParameters( ...
        blocks, inputs(index));
end
outputSinks = strings(size(outputs));
for index = 1:numel(outputs)
    outputSinks(index) = localFindByParameter( ...
        blocks, "VariableName", outputs(index));
end
audit = struct;
audit.locator_policy = ...
    "candidate public variable and Timeseries contracts; no golden block names or SID";
audit.mode = "candidate_public_contract";
audit.input_names = inputs;
audit.input_bindings = inputBindings;
audit.output_names = outputs;
audit.output_sinks = outputSinks;
audit.public_input_binding_fraction = ...
    mean(strlength(inputBindings) > 0);
audit.public_output_sink_fraction = ...
    mean(strlength(outputSinks) > 0);
reachability = false(numel(inputs), numel(outputs));
for inputIndex = 1:numel(inputs)
    for outputIndex = 1:numel(outputs)
        reachability(inputIndex, outputIndex) = localDirectedReachable( ...
            inputBindings(inputIndex), outputSinks(outputIndex));
    end
end
numericOutputs = 1:2:numel(outputs);
compiledTypes = strings(size(numericOutputs));
compiledFixedPoint = false(size(numericOutputs));
for index = 1:numel(numericOutputs)
    outputIndex = numericOutputs(index);
    types = localCompiledPortTypes(outputSinks(outputIndex));
    compiledTypes(index) = join(types, " | ");
    compiledFixedPoint(index) = localTypesHaveFixedPoint(types);
end
audit.public_io_reachability = reachability;
audit.numeric_output_names = outputs(numericOutputs);
audit.numeric_output_compiled_types = compiledTypes;
audit.numeric_output_fixed_point = compiledFixedPoint;
audit.fixed_point_evidence = all(compiledFixedPoint);
audit.behavioral_causality_required = true;
% Candidate architecture is unrestricted. Qualification therefore uses
% only declared public bindings, directed signal reachability, and the
% compiled types observed at the six numeric public output sinks.
audit.core_path_qualified = ...
    all(strlength(inputBindings) > 0) && ...
    all(strlength(outputSinks) > 0) && ...
    all(any(reachability, 1)) && ...
    all(any(reachability, 2)) && ...
    audit.fixed_point_evidence;
end

function generator = localInitializeGenerator(initScript)
% Run the exact source initializer in this function workspace so candidate
% models see only the four public evaluator inputs in the base workspace.
run(initScript);
generator = struct( ...
    "test_source_1", testSrc1, ...
    "test_source_2", testSrc2, ...
    "steering_object", steeringVector, ...
    "fc", fc, ...
    "num_elements", numArrayElements, ...
    "test_length", testLen, ...
    "adc_type", adc_dt, ...
    "input_type", input_dt, ...
    "steering_type", sv_dt, ...
    "pipeline_delay", mvdrPipelineDelay, ...
    "window_size", windowSize);
end

function generator = localGeneratorFromBase
generator = struct( ...
    "test_source_1", evalin("base", "testSrc1"), ...
    "test_source_2", evalin("base", "testSrc2"), ...
    "steering_object", evalin("base", "steeringVector"), ...
    "fc", evalin("base", "fc"), ...
    "num_elements", evalin("base", "numArrayElements"), ...
    "test_length", evalin("base", "testLen"), ...
    "adc_type", evalin("base", "adc_dt"), ...
    "input_type", evalin("base", "input_dt"), ...
    "steering_type", evalin("base", "sv_dt"), ...
    "pipeline_delay", evalin("base", "mvdrPipelineDelay"), ...
    "window_size", evalin("base", "windowSize"));
end

function [truth, requested] = ...
        localApplyScenario(scenario, generator, isReference)
testSrc1 = generator.test_source_1;
testSrc2 = generator.test_source_2;
steeringObject = generator.steering_object;
fc = generator.fc;
numElements = generator.num_elements;
testLen = generator.test_length;
adcType = generator.adc_type;
inputType = generator.input_type;
steeringType = generator.steering_type;
pipelineDelay = generator.pipeline_delay;

rng(double(scenario.seed), "twister");
targetWaveform = repmat(testSrc1.Data, ...
    ceil(testLen / numel(testSrc1.Data)), 1);
targetWaveform = targetWaveform(1:testLen) * ...
    double(scenario.target_gain);
interfererWaveform = repmat(testSrc2.Data, ...
    ceil(testLen / numel(testSrc2.Data)), 1);
interfererWaveform = interfererWaveform(1:testLen) * ...
    double(scenario.interferer_gain);

targetSteering = steeringObject(fc, ...
    [double(scenario.target_angle_deg); 0]);
interfererSteering = steeringObject(fc, ...
    [double(scenario.interferer_angle_deg); 0]);
targetComponent = bsxfun(@times, ...
    repmat(targetWaveform, 1, numElements), targetSteering.');
interfererComponent = bsxfun(@times, ...
    repmat(interfererWaveform, 1, numElements), ...
    interfererSteering.');
noise = complex(randn(testLen, numElements), ...
    randn(testLen, numElements)) * double(scenario.noise_gain);
mixture = targetComponent + interfererComponent + noise;
normalizer = max(abs(mixture(:)));
assert(isfinite(normalizer) && normalizer > 0, ...
    "SimuVerity:F90:XCOMM02:ScenarioNormalization", ...
    "Generated official array data cannot be normalized.");
mixture = mixture / normalizer * 0.5;
mixture = double(fi(mixture, adcType));
arrayData = fi(mixture, inputType);
inputValid = true(testLen, 1);
intervals = double(scenario.invalid_intervals_1based_inclusive);
if ~isempty(intervals)
    assert(size(intervals, 2) == 2, ...
        "SimuVerity:F90:XCOMM02:InvalidIntervals", ...
        "Invalid intervals must be an N-by-2 matrix.");
    for index = 1:size(intervals, 1)
        first = max(1, round(intervals(index, 1)));
        last = min(testLen, round(intervals(index, 2)));
        assert(first <= last, "SimuVerity:F90:XCOMM02:InvalidIntervalOrder", ...
            "Invalid sample interval is reversed.");
        inputValid(first:last) = false;
    end
end
assert(sum(inputValid) >= 2 * generator.window_size, ...
    "SimuVerity:F90:XCOMM02:InsufficientValidSamples", ...
    "A official scenario must retain at least two covariance windows.");
steeringVector = double(fi(targetSteering, steeringType));
diagonalLoading = double(scenario.DiagonalLoading);
stopTick = testLen + pipelineDelay;

if isReference
    assignin("base", "sim_data_in", arrayData);
    assignin("base", "sim_valid_in", inputValid);
    assignin("base", "sv", steeringVector);
    assignin("base", "diagLoading", diagonalLoading);
    assignin("base", "stoptime", stopTick);
end
assignin("base", "ArrayData", double(arrayData));
assignin("base", "InputValid", inputValid);
assignin("base", "SteeringVector", steeringVector);
assignin("base", "DiagonalLoading", diagonalLoading);

truth = struct( ...
    "id", string(scenario.id), ...
    "array_data", double(arrayData), ...
    "input_valid", inputValid, ...
    "steering_vector", steeringVector(:), ...
    "target_steering", targetSteering(:), ...
    "interferer_steering", interfererSteering(:), ...
    "target_waveform", targetWaveform / normalizer * 0.5, ...
    "diagonal_loading", diagonalLoading, ...
    "window_size", double(generator.window_size), ...
    "stop_tick", double(stopTick), ...
    "test_source", testSrc1);
requested = struct( ...
    "seed", double(scenario.seed), ...
    "target_angle_deg", double(scenario.target_angle_deg), ...
    "interferer_angle_deg", ...
        double(scenario.interferer_angle_deg), ...
    "target_gain", double(scenario.target_gain), ...
    "interferer_gain", double(scenario.interferer_gain), ...
    "noise_gain", double(scenario.noise_gain), ...
    "DiagonalLoading", diagonalLoading, ...
    "invalid_sample_count", sum(~inputValid));
end

function [summary, artifact, selected] = ...
        localExtractReferenceEvidence(simOut, truth)
[dataOut, outputTicks] = localNativeArray(simOut, "data_out");
[validOut, ~] = localNativeArray(simOut, "valid_out");
[weights, weightTicks] = localNativeArray(simOut, "w");
[weightValid, ~] = localNativeArray(simOut, "w_valid");
[wp, ~] = localNativeArray(simOut, "wp");
[wpValid, ~] = localNativeArray(simOut, "wp_valid");
[covariance, ~] = localNativeArray(simOut, "Ecx");
[covarianceScaled, ~] = localNativeArray(simOut, "Ecx_scaled");
[loadedCovariance, ~] = localNativeArray(simOut, "Ecx_loaded");
[matrixLatch, ~] = localNativeArray(simOut, "matrix_in_latch");
[normMagnitude, ~] = localNativeArray(simOut, "norm_mag");
[normValid, ~] = localNativeArray(simOut, "norm_mag_valid");
[normReciprocal, ~] = localNativeArray(simOut, "norm_mag_inv");
[normReciprocalValid, ~] = ...
    localNativeArray(simOut, "norm_mag_inv_valid");

validOut = logical(validOut(:));
weightValid = logical(weightValid(:));
wpValid = logical(wpValid(:));
matrixLatch = logical(matrixLatch(:));
normValid = logical(normValid(:));
normReciprocalValid = logical(normReciprocalValid(:));
assert(size(dataOut, 1) == numel(validOut), ...
    "SimuVerity:F90:XCOMM02:OutputValidShape", ...
    "data_out and valid_out do not align.");
assert(size(weights, 1) == numel(weightValid), ...
    "SimuVerity:F90:XCOMM02:WeightValidShape", ...
    "w and w_valid do not align.");

latchIndex = find(matrixLatch);
assert(any(validOut) && any(weightValid) && ...
    any(wpValid) && ~isempty(latchIndex), ...
    "SimuVerity:F90:XCOMM02:MissingNativeEvidence", ...
    "Native output, weight, solve, or covariance evidence is empty.");
assert(all(latchIndex > 2), "SimuVerity:F90:XCOMM02:CovarianceLatch", ...
    "Covariance latch index is inconsistent with the native pipeline.");

covarianceAtLatch = covarianceScaled(latchIndex - 2, :);
loadedAtLatch = loadedCovariance(latchIndex, :);
[refCovariance, refLoaded, ~, refWeights] = ...
    localFloatingReference(truth);
summary = localComputeSummary( ...
    dataOut, outputTicks, validOut, ...
    weights, weightTicks, weightValid, ...
    wp, wpValid, covarianceAtLatch, loadedAtLatch, ...
    refCovariance, refLoaded, refWeights, truth, numel(latchIndex));

artifact = localEmptyArtifact;
artifact.id = truth.id;
artifact.input_array = truth.array_data;
artifact.input_valid = truth.input_valid;
artifact.steering_vector = truth.steering_vector;
artifact.target_steering = truth.target_steering;
artifact.interferer_steering = truth.interferer_steering;
artifact.diagonal_loading = truth.diagonal_loading;
artifact.output_ticks = outputTicks;
artifact.beamformed_output = dataOut;
artifact.output_valid = validOut;
artifact.weight_ticks = weightTicks;
artifact.weight_vector = weights;
artifact.weight_valid = weightValid;
artifact.covariance = covariance;
artifact.covariance_scaled = covarianceScaled;
artifact.loaded_covariance = loadedCovariance;
artifact.covariance_latch = matrixLatch;
artifact.solve_vector = wp;
artifact.solve_valid = wpValid;
artifact.normalization_magnitude = normMagnitude;
artifact.normalization_valid = normValid;
artifact.normalization_reciprocal = normReciprocal;
artifact.normalization_reciprocal_valid = normReciprocalValid;

selected = struct( ...
    "input_data", "sim_data_in", ...
    "input_valid", "sim_valid_in", ...
    "beamformed_output", "data_out", ...
    "output_valid", "valid_out", ...
    "covariance", "Ecx", ...
    "scaled_covariance", "Ecx_scaled", ...
    "loaded_covariance", "Ecx_loaded", ...
    "solve_vector", "wp", ...
    "weight_vector", "w", ...
    "normalization", "norm_mag/norm_mag_inv");
end

function [summary, artifact, selected] = ...
        localExtractPublicEvidence(simOut, truth)
[dataOut, outputTicks, validOut] = localPublicPair( ...
    simOut, "BeamformedOutput", "OutputValid", 1, "complex", truth);
[weights, weightTicks, weightValid] = localPublicPair( ...
    simOut, "WeightVector", "WeightValid", 4, "complex", truth);
[covariance, ~, covarianceValid] = localPublicPair( ...
    simOut, "CovarianceMatrix", "CovarianceValid", ...
    16, "complex", truth);
[loadedCovariance, ~, loadedValid] = localPublicPair( ...
    simOut, "LoadedCovarianceMatrix", ...
    "LoadedCovarianceValid", 16, "complex", truth);
[wp, ~, wpValid] = localPublicPair( ...
    simOut, "SolveVector", "SolveValid", 4, "complex", truth);
[normalization, ~, normValid] = localPublicPair( ...
    simOut, "NormalizationState", ...
    "NormalizationValid", 2, "real", truth);

covarianceAtLatch = covariance(covarianceValid, :);
loadedAtLatch = loadedCovariance(loadedValid, :);
[refCovariance, refLoaded, ~, refWeights] = ...
    localFloatingReference(truth);
summary = localComputeSummary( ...
    dataOut, outputTicks, validOut, ...
    weights, weightTicks, weightValid, ...
    wp, wpValid, covarianceAtLatch, loadedAtLatch, ...
    refCovariance, refLoaded, refWeights, truth, ...
    sum(covarianceValid));
validNormalization = normalization(normValid, :);
summary.normalization_pair_identity_error_max = ...
    max(abs(validNormalization(:, 1) .* ...
    validNormalization(:, 2) - 1));

artifact = localEmptyArtifact;
artifact.id = truth.id;
artifact.input_array = truth.array_data;
artifact.input_valid = truth.input_valid;
artifact.steering_vector = truth.steering_vector;
artifact.target_steering = truth.target_steering;
artifact.interferer_steering = truth.interferer_steering;
artifact.diagonal_loading = truth.diagonal_loading;
artifact.output_ticks = outputTicks;
artifact.beamformed_output = dataOut;
artifact.output_valid = validOut;
artifact.weight_ticks = weightTicks;
artifact.weight_vector = weights;
artifact.weight_valid = weightValid;
artifact.covariance = covariance;
artifact.covariance_scaled = covariance;
artifact.loaded_covariance = loadedCovariance;
artifact.covariance_latch = covarianceValid;
artifact.solve_vector = wp;
artifact.solve_valid = wpValid;
artifact.normalization_magnitude = normalization(:, 1);
artifact.normalization_valid = normValid;
artifact.normalization_reciprocal = normalization(:, 2);
artifact.normalization_reciprocal_valid = normValid;

selected = struct( ...
    "adapter", "public_timeseries_contract", ...
    "input_data", "ArrayData", ...
    "input_valid", "InputValid", ...
    "beamformed_output", "BeamformedOutput/OutputValid", ...
    "covariance", "CovarianceMatrix/CovarianceValid", ...
    "loaded_covariance", ...
        "LoadedCovarianceMatrix/LoadedCovarianceValid", ...
    "solve_vector", "SolveVector/SolveValid", ...
    "weight_vector", "WeightVector/WeightValid", ...
    "normalization", ...
        "NormalizationState/NormalizationValid");
end

function summary = localComputeSummary( ...
        dataOut, outputTicks, validOut, ...
        weights, weightTicks, weightValid, ...
        wp, wpValid, covarianceAtLatch, loadedAtLatch, ...
        refCovariance, refLoaded, refWeights, truth, updateCount)
validOut = logical(validOut(:));
weightValid = logical(weightValid(:));
wpValid = logical(wpValid(:));
assert(size(dataOut, 1) == numel(validOut), ...
    "SimuVerity:F90:XCOMM02:OutputValidShape", ...
    "Beam output and output valid do not align.");
assert(size(weights, 1) == numel(weightValid), ...
    "SimuVerity:F90:XCOMM02:WeightValidShape", ...
    "Weight vector and weight valid do not align.");
beamformed = dataOut(validOut, :);
validWeights = weights(weightValid, :);
validWp = wp(wpValid, :);
count = min([size(covarianceAtLatch, 1), ...
    size(loadedAtLatch, 1), size(refCovariance, 1), ...
    size(validWeights, 1), size(validWp, 1), ...
    size(refWeights, 1)]);
assert(~isempty(beamformed) && count >= 2, ...
    "SimuVerity:F90:XCOMM02:AdaptationCount", ...
    "At least two complete valid adaptation updates are required.");
covarianceAtLatch = covarianceAtLatch(1:count, :);
loadedAtLatch = loadedAtLatch(1:count, :);
validWeights = validWeights(1:count, :);
validWp = validWp(1:count, :);
refCovariance = refCovariance(1:count, :);
refLoaded = refLoaded(1:count, :);
refWeights = refWeights(1:count, :);

solveResiduals = zeros(count, 1);
hermitianResiduals = zeros(count, 1);
targetResponses = zeros(count, 1);
interfererResponses = zeros(count, 1);
normalizationErrors = zeros(count, 1);
for index = 1:count
    loadedMatrix = reshape(loadedAtLatch(index, :), 4, 4);
    covarianceMatrix = reshape(covarianceAtLatch(index, :), 4, 4);
    solveVector = validWp(index, :).';
    weightVector = validWeights(index, :).';
    solveResiduals(index) = norm(loadedMatrix * solveVector - ...
        truth.steering_vector) / max(norm(truth.steering_vector), eps);
    hermitianResiduals(index) = norm(covarianceMatrix - ...
        covarianceMatrix', "fro") / ...
        max(norm(covarianceMatrix, "fro"), eps);
    targetResponses(index) = abs(truth.target_steering.' * ...
        conj(weightVector));
    interfererResponses(index) = abs( ...
        truth.interferer_steering.' * conj(weightVector));
    normalizationErrors(index) = abs( ...
        truth.steering_vector' * weightVector - 1);
end

constellation = qpsk_receive(beamformed(:), truth.test_source);
constellation = constellation(:);
constellation = constellation / max( ...
    sqrt(mean(abs(constellation).^2)), eps);
ideal = exp(1j * (pi / 4 + (0:3) * pi / 2));
nearestSquared = min(abs(constellation - ideal).^2, [], 2);
qpskEvm = sqrt(mean(nearestSquared));
nullDepth = 20 * log10(max(targetResponses, eps) ./ ...
    max(interfererResponses, eps));

weightUpdateTicks = weightTicks(weightValid);
updateIntervals = diff(weightUpdateTicks);
expectedInputTicks = find(truth.input_valid) - 1;
expectedUpdateTicks = expectedInputTicks( ...
    truth.window_size:truth.window_size:end);
expectedIntervals = diff(expectedUpdateTicks);
intervalCount = min(numel(updateIntervals), ...
    numel(expectedIntervals));
if intervalCount > 0
    cadenceError = median(abs( ...
        updateIntervals(1:intervalCount) - ...
        expectedIntervals(1:intervalCount)) ./ ...
        max(expectedIntervals(1:intervalCount), 1));
else
    cadenceError = Inf;
end
successiveWeightChange = vecnorm(diff(validWeights, 1, 1), 2, 2) ./ ...
    max(vecnorm(validWeights(2:end, :), 2, 2), eps);

summary = struct( ...
    "output_valid_count", sum(validOut), ...
    "weight_update_count", sum(weightValid), ...
    "covariance_update_count", updateCount, ...
    "input_invalid_sample_count", sum(~truth.input_valid), ...
    "first_output_valid_tick", ...
        double(outputTicks(find(validOut, 1, "first"))), ...
    "first_weight_valid_tick", double(weightUpdateTicks(1)), ...
    "median_weight_update_interval", ...
        double(median(updateIntervals, "omitnan")), ...
    "weight_update_interval_relative_error", ...
        double(cadenceError), ...
    "qpsk_decision_evm", double(qpskEvm), ...
    "target_response_error_max", ...
        double(max(abs(targetResponses - 1))), ...
    "target_response_error_median", ...
        double(median(abs(targetResponses - 1))), ...
    "interferer_null_depth_db_min", double(min(nullDepth)), ...
    "interferer_null_depth_db_median", double(median(nullDepth)), ...
    "weight_noise_gain_max", ...
        double(max(vecnorm(validWeights, 2, 2))), ...
    "covariance_relative_rmse", ...
        double(localRelativeRmse(covarianceAtLatch, refCovariance)), ...
    "loaded_covariance_relative_rmse", ...
        double(localRelativeRmse(loadedAtLatch, refLoaded)), ...
    "weight_relative_rmse", ...
        double(localRelativeRmse(validWeights, refWeights)), ...
    "solve_residual_max", double(max(solveResiduals)), ...
    "normalization_error_max", double(max(normalizationErrors)), ...
    "covariance_hermitian_residual_max", ...
        double(max(hermitianResiduals)), ...
    "successive_weight_change_tail", ...
        double(successiveWeightChange(end)), ...
    "final_weight_real", real(validWeights(end, :)), ...
    "final_weight_imag", imag(validWeights(end, :)), ...
    "output_peak", double(max(abs(beamformed))), ...
    "all_native_values_finite", ...
        all(isfinite(real(beamformed)), "all") && ...
        all(isfinite(imag(beamformed)), "all") && ...
        all(isfinite(real(validWeights)), "all") && ...
        all(isfinite(imag(validWeights)), "all"));
end

function [covariance, loaded, solveVector, weights] = ...
        localFloatingReference(truth)
validData = truth.array_data(logical(truth.input_valid), :);
count = floor(size(validData, 1) / truth.window_size);
assert(count >= 2, "SimuVerity:F90:XCOMM02:ReferenceWindowCount", ...
    "Fewer than two valid covariance windows are available.");
covariance = complex(zeros(count, 16));
loaded = complex(zeros(count, 16));
solveVector = complex(zeros(count, 4));
weights = complex(zeros(count, 4));
for index = 1:count
    first = (index - 1) * truth.window_size + 1;
    last = index * truth.window_size;
    window = validData(first:last, :);
    matrix = (window.' * conj(window)) / truth.window_size;
    loadedMatrix = matrix + eye(4) * truth.diagonal_loading;
    unnormalized = loadedMatrix \ truth.steering_vector;
    normalizer = real(truth.steering_vector' * unnormalized);
    weight = unnormalized / normalizer;
    covariance(index, :) = reshape(matrix, 1, []);
    loaded(index, :) = reshape(loadedMatrix, 1, []);
    solveVector(index, :) = unnormalized.';
    weights(index, :) = weight.';
end
end

function [data, ticks, valid] = localPublicPair( ...
        simOut, dataName, validName, channels, valueKind, truth)
[data, ticks] = localRequiredTimeseries(simOut, dataName, channels);
[validData, validTicks] = localRequiredTimeseries(simOut, validName, 1);
assert(numel(ticks) == numel(validTicks) && ...
    all(abs(ticks - validTicks) <= 1e-9), ...
    "SimuVerity:F90:XCOMM02:PublicPairTime", ...
    "%s and %s must have the same Time vector.", ...
    dataName, validName);
assert(size(data, 2) == channels, ...
    "SimuVerity:F90:XCOMM02:PublicChannels", ...
    "%s must have exactly %d channels.", dataName, channels);
assert(size(validData, 2) == 1 && ...
    all(validData(:) == 0 | validData(:) == 1), ...
    "SimuVerity:F90:XCOMM02:PublicValidContract", ...
    "%s must be a one-channel logical validity signal.", validName);
assert(all(ticks >= -1e-9) && ...
    all(ticks <= truth.stop_tick + 1e-9), ...
    "SimuVerity:F90:XCOMM02:PublicTimeRange", ...
    "%s contains timestamps outside the evaluator run.", dataName);
if valueKind == "complex"
    assert(~isreal(data) && any(abs(imag(data(:))) > 1e-12), ...
        "SimuVerity:F90:XCOMM02:PublicComplexContract", ...
        "%s must preserve complex-valued data.", dataName);
elseif valueKind == "real"
    assert(isreal(data), "SimuVerity:F90:XCOMM02:PublicRealContract", ...
        "%s must be real-valued.", dataName);
end
valid = logical(validData(:));
assert(any(valid), "SimuVerity:F90:XCOMM02:PublicNoValidSamples", ...
    "%s never becomes true.", validName);
end

function [data, ticks] = localRequiredTimeseries(simOut, name, width)
value = simuverity_public_output_compatibility( ...
    simOut,string(name),width,AllowBaseWorkspace=true);
ticks = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data)
    data = data(:);
elseif size(data, 1) ~= numel(ticks) && ...
        size(data, 2) == numel(ticks)
    data = data.';
end
assert(size(data, 1) == numel(ticks) && ...
    numel(ticks) >= 2 && all(isfinite(ticks)) && ...
    all(diff(ticks) > 0), ...
    "SimuVerity:F90:XCOMM02:PublicTimeseriesShape", ...
    "%s has invalid time or data dimensions.", name);
end

function localClearEvidenceOutputs(isReference)
if isReference
    names = ["data_out", "valid_out", "w", "w_valid", ...
        "wp", "wp_valid", "Ecx", "Ecx_scaled", "Ecx_loaded", ...
        "matrix_in_latch", "norm_mag", "norm_mag_valid", ...
        "norm_mag_inv", "norm_mag_inv_valid"];
else
    names = ["BeamformedOutput", "OutputValid", ...
        "WeightVector", "WeightValid", ...
        "CovarianceMatrix", "CovarianceValid", ...
        "LoadedCovarianceMatrix", "LoadedCovarianceValid", ...
        "SolveVector", "SolveValid", ...
        "NormalizationState", "NormalizationValid"];
end
evalin("base", "clear " + join(names, " "));
end

function value = localRelativeRmse(actual, reference)
delta = double(actual) - double(reference);
value = sqrt(mean(abs(delta(:)).^2)) / ...
    max(sqrt(mean(abs(double(reference(:))).^2)), eps);
end

function [data, ticks] = localNativeArray(simOut, name)
value = [];
try
    value = simOut.get(name);
catch
end
if isempty(value)
    try
        if evalin("base", "exist('" + name + "','var')")
            value = evalin("base", name);
        end
    catch
    end
end
assert(~isempty(value), "SimuVerity:F90:XCOMM02:NativeSignalMissing", ...
    "Required native signal %s is missing.", name);
if isa(value, "timeseries") || isa(value, "Simulink.Timeseries")
    data = squeeze(double(value.Data));
    ticks = double(value.Time(:));
else
    data = squeeze(double(value));
    if isvector(data), data = data(:); end
    ticks = (0:(size(data, 1) - 1)).';
end
if isvector(data) && numel(data) == numel(ticks)
    data = data(:);
end
assert(size(data, 1) == numel(ticks), ...
    "SimuVerity:F90:XCOMM02:NativeSignalShape", ...
    "Native signal %s has inconsistent time and data dimensions.", name);
end

function block = localFindByParameter(blocks, parameter, expected)
block = "";
for index = 1:numel(blocks)
    value = localGet(blocks(index), parameter);
    if strcmp(strtrim(value), expected)
        block = blocks(index);
        return;
    end
end
end

function block = localFindByContains(blocks, parameter, token)
block = "";
for index = 1:numel(blocks)
    value = localGet(blocks(index), parameter);
    if contains(lower(value), lower(token))
        block = blocks(index);
        return;
    end
end
end

function block = localFindTokenAcrossParameters(blocks, token)
parameters = ["VariableName", "Variable", "X", "Value", ...
    "Data", "Expression", "MaskValueString"];
block = "";
for blockIndex = 1:numel(blocks)
    for parameterIndex = 1:numel(parameters)
        value = localGet(blocks(blockIndex), ...
            parameters(parameterIndex));
        if contains(lower(value), lower(token))
            block = blocks(blockIndex);
            return;
        end
    end
end
end

function [compiledTypes, fixedPoint] = ...
        localCompiledFixedPointEvidence(blocks)
compiledTypes = strings(size(blocks));
fixedPoint = false(size(blocks));
for index = 1:numel(blocks)
    types = localCompiledPortTypes(blocks(index));
    compiledTypes(index) = join(types, " | ");
    fixedPoint(index) = localTypesHaveFixedPoint(types);
end
end

function types = localCompiledPortTypes(block)
types = strings(0, 1);
if strlength(block) == 0, return; end
try
    compiled = get_param(block, "CompiledPortDataTypes");
catch
    return;
end
fields = fieldnames(compiled);
for fieldIndex = 1:numel(fields)
    values = compiled.(fields{fieldIndex});
    if ischar(values)
        types = [types; string(values)]; %#ok<AGROW>
    elseif isstring(values)
        types = [types; values(:)]; %#ok<AGROW>
    elseif iscell(values)
        for valueIndex = 1:numel(values)
            try
                types(end + 1, 1) = string(values{valueIndex}); %#ok<AGROW>
            catch
            end
        end
    end
end
types = strtrim(types);
types = unique(types(strlength(types) > 0), "stable");
end

function pass = localTypesHaveFixedPoint(types)
tokens = ["fixdt", "sfix", "ufix", "fixed-point", "fixed point"];
signature = lower(join(types, " "));
pass = strlength(signature) > 0 && any(contains(signature, tokens));
end

function value = localGet(block, parameter)
value = "";
if strlength(block) == 0, return; end
try
    value = string(get_param(block, parameter));
catch
end
end

function pass = localDirectedReachable(source, target)
pass = false;
sourceHandle = getSimulinkBlockHandle(source, false);
targetHandle = getSimulinkBlockHandle(target, false);
if sourceHandle <= 0 || targetHandle <= 0, return; end
queue = sourceHandle;
visited = zeros(0, 1);
while ~isempty(queue)
    current = queue(1);
    queue(1) = [];
    if current == targetHandle
        pass = true;
        return;
    end
    if any(visited == current), continue; end
    visited(end + 1, 1) = current; %#ok<AGROW>
    try
        connectivity = get_param(current, "PortConnectivity");
    catch
        connectivity = struct([]);
    end
    for index = 1:numel(connectivity)
        neighbors = double(connectivity(index).DstBlock(:));
        neighbors = neighbors(isfinite(neighbors) & neighbors > 0);
        queue = [queue; neighbors]; %#ok<AGROW>
    end
end
end

