function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function value = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
value = "present";
end

function value = localQuote(path)
value = replace(string(path), "'", "''");
end

function value = localNow
value = string(datetime("now", "TimeZone", "local", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end

function out = localError(ME)
out = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message), ...
    "report", string(getReport(ME, "extended", ...
        "hyperlinks", "off")));
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid >= 0, "SimuVerity:F90:XCOMM02:WriteJson", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, "PrettyPrint", false), "char");
end
